// Force transcript to be a clean string safely
if (typeof transcript !== 'string') {
  try {
    transcript = JSON.stringify(transcript) || '';
  } catch (e) {
    transcript = String(transcript || '');
  }
}
transcript = transcript.trim();

// 2. Extract Caller / Patient Phone Number
